import json
d=json.load(open('/opt/runtime/dependency-union.json'))
for k,v in d.items():
    if isinstance(v,(str,int,float,bool)) or v is None:
        print(k,'=',str(v)[:200])
    elif isinstance(v,list):
        print(k,':list len',len(v), str(v[:8])[:300])
    elif isinstance(v,dict):
        print(k,':dict keys',list(v)[:10])
EOF

